function openGateway(id,scroll=true){navigationToken++;selected=id;root=id;trail=[nodes.get(id).title];pathHighlight=[];zoom=1;pan={x:0,y:0};activeReaderTab='idea';render();persist();if(scroll)$('#explorer').scrollIntoView({behavior:'smooth',block:'start'});}
