  const label=svg('text',{x:0,y:26,'text-anchor':'middle',class:'node-label'});if(view==='atlas')label.style.fontSize='10px';const display=n.title.length>(view==='atlas'?23:29)?n.title.slice(0,view==='atlas'?21:27)+'…':n.title;label.textContent=display;group.append(label);
