 const tabs=el('div','reader-tabs');tabs.setAttribute('role','tablist');for(const [id,label]of [['idea','The idea'],['sources','Provenance'],['notes','Your notes']]){const b=el('button','',label);b.setAttribute('role','tab');b.setAttribute('aria-selected',String(activeReaderTab===id));b.onclick=()=>{activeReaderTab=id;renderReader();};tabs.append(b);}panel.append(tabs);
