async function expandNode(n,button){
 const originId=n.id;button.disabled=true;button.textContent='Finding connected articles…';
 try{const {node,related:found}=await relatedArticles(n.title);if(!found.length){toast('No further article links were available.');return;}
  // Preserve the editorial note while attaching link evidence to its canonical source.
  const additional=found.filter(c=>!nodeByTitle(c.title));if(nodes.size+additional.length>180)throw new Error('This expansion would exceed 180 ideas. Export your workspace before starting a fresh map.');for(const candidate of found){const next=addNode(candidate);edges=mergeEdge(edges,{from:originId,to:next.id,kind:'article',source:node.source.url,label:'Article link · ranked by text overlap'});}layoutCache=null;persist();render();toast(`${found.length} source-linked ideas added to your map.`);
 }catch(error){toast(error.message||'Could not expand this idea. Your map is unchanged.');}
 finally{if(document.contains(button)){button.disabled=false;button.textContent='Explore article links ↗';}}
}
function hideSearch(){$('#search-results').hidden=true;searchController?.abort();}
function showSearchResults(items,{remote=false}={}){const list=$('#result-items');for(const item of items){const title=item.title;if([...list.children].some(b=>b.dataset.title===title))continue;const b=el('button','search-result',title);b.dataset.title=title;const summary=remote?new DOMParser().parseFromString(item.snippet||'','text/html').body.textContent:item.category;b.append(el('span','',summary));b.onclick=()=>{hideSearch();$('#search').value='';goTo(title,{startNew:true});$('#explorer').scrollIntoView({behavior:'smooth'});};list.append(b);}}
$('#search-form').addEventListener('submit',async ev=>{ev.preventDefault();const query=$('#search').value.trim();if(!query){$('#search').focus();return;}searchController?.abort();searchController=new AbortController();const controller=searchController;$('#search-results').hidden=false;$('#result-items').replaceChildren();$('#search-label').textContent='SEARCHING THE MAP + WIKIPEDIA';$('#search-note').textContent='Looking beyond the starter map…';const local=searchLocal([...nodes.values()],query);showSearchResults(local);
 try{const results=await searchWikipedia(query,controller.signal);if(controller!==searchController)return;showSearchResults(results,{remote:true});$('#search-label').textContent=`${$('#result-items').children.length} THREADS TO FOLLOW`;$('#search-note').textContent=results.length?'Live results from Wikipedia. Choose an idea to begin.':local.length?'Matches from your loaded map.':'No results. Try a shorter topic, such as “jazz”, “architecture” or “ocean”.';}
 catch(error){if(controller.signal.aborted)return;$('#search-label').textContent=local.length?'FROM YOUR LOADED MAP':'LIVE SEARCH UNAVAILABLE';$('#search-note').textContent=`${error.message||'Could not reach Wikipedia.'} You can still explore the starter doors below.`;}
});
$('#close-search').onclick=hideSearch;document.addEventListener('click',e=>{if(!e.target.closest('.search-strip'))hideSearch();});
$('#surprise').onclick=()=>{const options=GATEWAYS.filter(g=>g.id!==root);openGateway(options[Math.floor(Math.random()*options.length)].id);};
$('#gateways').replaceChildren(...GATEWAYS.map((g,i)=>{const b=el('button','gateway');b.style.setProperty('--card-color',COLORS[g.category]);b.append(el('span','eyebrow',`${String(i+1).padStart(2,'0')} / ${g.category.toUpperCase()}`),el('span','symbol',g.symbol),el('h3','',g.title),el('p','',g.hint),el('span','arrow','↗'));b.onclick=()=>openGateway(g.id);return b;}));
$('#reset-map').onclick=()=>openGateway(root,false);$('#focus-view').onclick=()=>{view='focus';zoom=1;pan={x:0,y:0};renderGraph();};$('#atlas-view').onclick=()=>{view='atlas';zoom=1;pan={x:0,y:0};renderGraph();};
$('#zoom-in').onclick=()=>{zoom=Math.min(2.4,zoom+.2);updateTransform();};$('#zoom-out').onclick=()=>{zoom=Math.max(.6,zoom-.2);updateTransform();};$('#zoom-reset').onclick=()=>{zoom=1;pan={x:0,y:0};updateTransform();};
let drag=null;$('#graph').addEventListener('pointerdown',e=>{if(e.target.closest('.graph-node'))return;drag={x:e.clientX,y:e.clientY,pan:{...pan}};$('#graph').setPointerCapture(e.pointerId);});$('#graph').addEventListener('pointermove',e=>{if(!drag)return;const scale=900/$('#graph').getBoundingClientRect().width;pan.x=drag.pan.x+(e.clientX-drag.x)*scale;pan.y=drag.pan.y+(e.clientY-drag.y)*scale;updateTransform();});$('#graph').addEventListener('pointerup',()=>drag=null);$('#graph').addEventListener('pointercancel',()=>drag=null);
function openDialog(id){$(id).showModal();}
$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$$('dialog').forEach(d=>d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close();}}));
$('#open-about').onclick=$('#footer-about').onclick=()=>openDialog('#about-dialog');
$('#save-trail').onclick=()=>{$('#trail-name').value=trail.length>1?`${trail[0]} → ${trail.at(-1)}`:`A little curiosity about ${trail[0]}`;openDialog('#save-dialog');};
$('#save-form').onsubmit=ev=>{ev.preventDefault();if(saved.length>=LIMITS.saved){toast('You have 50 saved trails. Export them or remove one to make room.');return;}const name=$('#trail-name').value.trim();if(!name)return;const item={id:crypto.randomUUID(),name,date:new Date().toISOString(),titles:[...trail]};saved.unshift(item);const ok=persistSaved();$('#save-dialog').close();toast(ok?'Trail saved. A little curiosity, kept.':'Trail saved for this session. Export it because browser storage is unavailable.');};
function download(filename,text,type='text/markdown'){const blob=new Blob([text],{type:`${type};charset=utf-8`});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function restoreTrail(titles){if(!titles.length)return;const last=titles.at(-1);await goTo(last,{append:false});if(nodes.get(selected)?.title.toLowerCase()!==last.toLowerCase())return;trail=[...titles];root=nodeByTitle(titles[0])?.id||selected;pathHighlight=[];render();persist();$('#explorer').scrollIntoView({behavior:'smooth'});}
function renderSaves(){const list=$('#saved-list');list.replaceChildren();if(!saved.length){list.append(el('p','empty-saves','Nothing saved yet. Follow a few ideas, then use “Save trail” to keep your path.'));}for(const item of saved){const card=el('article','saved-item');card.append(el('h3','',item.name),el('p','',`${item.titles.length} stops · ${new Date(item.date).toLocaleDateString()}`),el('p','',item.titles.join(' → ')));const actions=el('div','saved-actions');const open=el('button','','Continue ↗');open.onclick=()=>{$('#trails-dialog').close();restoreTrail(item.titles);};const exp=el('button','','Export ↓');exp.onclick=()=>download('rabbit-hole-trail.md',toMarkdown(item.name,item.titles,[...nodes.values()]));const remove=el('button','','Remove');remove.setAttribute('aria-label',`Remove trail ${item.name}`);remove.onclick=()=>{saved=saved.filter(x=>x.id!==item.id);persistSaved();renderSaves();toast('Trail removed from this browser.');};actions.append(open,exp,remove);card.append(actions);list.append(card);}}
$('#open-trails').onclick=()=>{renderSaves();openDialog('#trails-dialog');};
$('#export-current').onclick=()=>download('rabbit-hole-trail.md',toMarkdown('My Rabbit Hole trail',trail,[...nodes.values()]));
$('#export-all').onclick=()=>{if(!saved.length){toast('Save a trail first.');return;}download('rabbit-hole-trails.md',saved.map(s=>toMarkdown(s.name,s.titles,[...nodes.values()])).join('\n---\n\n'));};
$('#export-workspace').onclick=()=>download('rabbit-hole-workspace.json',JSON.stringify(workspace(),null,2),'application/json');
$('#import-workspace').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('Choose a workspace smaller than 2 MB.');const incoming=validateWorkspace(JSON.parse(await file.text()));const merged=new Map(nodes);incoming.nodes.forEach(n=>{if(!merged.has(n.id))merged.set(n.id,n);});if(merged.size>180)throw new Error('The merged workspace would exceed 180 ideas. Nothing was changed.');let combined=edges;for(const e of incoming.edges)combined=mergeEdge(combined,e);if(combined.length>1600)throw new Error('The merged workspace has too many connections. Nothing was changed.');const combinedNotes=[...notes,...incoming.notes.filter(n=>!notes.some(old=>old.id===n.id))];if(combinedNotes.length>300)throw new Error('The merged notebook would exceed 300 observations.');nodes=merged;edges=combined;notes=combinedNotes;layoutCache=null;persist();render();$('#trails-dialog').close();toast(`Imported ${incoming.nodes.length} ideas and ${incoming.notes.length} notes. Existing content kept.`);}catch(error){toast(error.message||'Could not read that workspace.');}finally{ev.target.value='';}};
$('#share-trail').onclick=async()=>{const url=new URL(location.href);url.hash=encodeTrail(trail).slice(1);try{await navigator.clipboard.writeText(url.href);toast('Trail link copied. It includes the topic titles.');}catch{download('rabbit-hole-trail-link.txt',url.href,'text/plain');toast('Clipboard unavailable. The trail link was downloaded.');}};
function openNote(nodeId,note=null){noteEditId=note?.id||null;$('#note-form').dataset.nodeId=nodeId;$('#note-title').textContent=`On ${nodes.get(nodeId)?.title||'this idea'}.`;$('#note-text').value=note?.text||'';openDialog('#note-dialog');$('#note-text').focus();}
$('#note-form').onsubmit=ev=>{ev.preventDefault();const text=$('#note-text').value.trim();if(!text)return;if(!noteEditId&&notes.length>=300){toast('Notebook limit reached. Export your notes before making space.');return;}const note={id:noteEditId||crypto.randomUUID(),nodeId:ev.target.dataset.nodeId,text,date:new Date().toISOString()};if(noteEditId)notes=notes.map(n=>n.id===noteEditId?note:n);else notes.push(note);persist();$('#note-dialog').close();renderReader();if($('#notebook-dialog').open)renderNotebook();toast('Observation saved with its source.');};
function renderNotebook(){const list=$('#notebook-list');list.replaceChildren();if(!notes.length)list.append(el('p','empty-saves','Your notebook is waiting. Open an idea and add an observation.'));for(const note of [...notes].reverse()){const n=nodes.get(note.nodeId);const card=el('article','notebook-item');card.append(el('h3','',n?.title||'Idea'),el('p','',note.text));if(n)card.append(sourceAnchor(n));const actions=el('div','saved-actions');const edit=el('button','','Edit');edit.onclick=()=>openNote(note.nodeId,note);const open=el('button','','Explore idea ↗');open.onclick=()=>{$('#notebook-dialog').close();goTo(n.title);};const remove=el('button','','Remove');remove.setAttribute('aria-label',`Remove observation on ${n.title}`);remove.onclick=()=>{notes=notes.filter(x=>x.id!==note.id);persist();renderNotebook();renderReader();};actions.append(edit,open,remove);card.append(actions);list.append(card);}}
$('#open-notebook').onclick=()=>{renderNotebook();openDialog('#notebook-dialog');};
$('#export-notes').onclick=()=>{if(!notes.length){toast('Add an observation first.');return;}download('rabbit-hole-notebook.md','# Rabbit Hole notebook\n\n'+notes.map(note=>{const n=nodes.get(note.nodeId);return `## ${n?.title||'Idea'}\n\n${note.text}\n\nSource: ${n?.source.url||''}\n\nRecorded: ${note.date}\n`;}).join('\n---\n\n'));};
$('#find-path').onclick=()=>{const options=[...nodes.values()].sort((a,b)=>a.title.localeCompare(b.title));for(const selector of ['#path-from','#path-to']){$(selector).replaceChildren(...options.map(n=>{const o=el('option','',n.title);o.value=n.id;return o;}));}$('#path-from').value=selected;$('#path-to').value=selected==='moon'?'music':'moon';$('#path-result').textContent='';openDialog('#path-dialog');};
$('#path-form').onsubmit=ev=>{ev.preventDefault();const path=shortestPath(edges,$('#path-from').value,$('#path-to').value);if(!path){$('#path-result').textContent='These ideas are not connected in your loaded map yet. Expand their article links and try again.';return;}pathHighlight=path;view='atlas';zoom=1;pan={x:0,y:0};$('#path-dialog').close();renderGraph();toast(`${path.length-1} connections. Follow the highlighted route.`);};
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')hideSearch();const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName);if(ev.key==='/'&&!editing&&!$('dialog[open]')){ev.preventDefault();$('#search').focus();}if(ev.key==='s'&&!editing&&!$('dialog[open]')){$('#save-trail').click();}});
render();const shared=decodeTrail(location.hash);if(shared.length){restoreTrail(shared);}else persist();
window.addEventListener('hashchange',()=>{const titles=decodeTrail(location.hash);if(titles.length)restoreTrail(titles);});

function decorateArrows(root){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const texts=[];if(root.nodeType===Node.TEXT_NODE)texts.push(root);else while(walker.nextNode())texts.push(walker.currentNode);
 for(const text of texts){if(!text.nodeValue.includes('↗')||text.parentElement?.closest('script,style,textarea,svg'))continue;const fragment=document.createDocumentFragment();const pieces=text.nodeValue.split('↗');pieces.forEach((p,i)=>{if(p)fragment.append(document.createTextNode(p));if(i<pieces.length-1){const icon=el('span','arrow-icon');icon.setAttribute('aria-hidden','true');fragment.append(icon);}});text.replaceWith(fragment);}
}
decorateArrows(document.body);new MutationObserver(records=>{for(const r of records)for(const node of r.addedNodes)if(node.nodeType===Node.ELEMENT_NODE||node.nodeType===Node.TEXT_NODE)decorateArrows(node);}).observe(document.body,{childList:true,subtree:true});
